import pygame
from tile import Tile
from board import Board

pygame.init()
screen = pygame.display.set_mode((640, 480))
clock = pygame.time.Clock()
running = True

sz = 26

board = Board(size=sz)
board.show_empty = True

board.generate_empty()

sel_board = None
sel_x = None
sel_y = None

my_font = pygame.font.SysFont("Arial", 72, bold=True)
to_view = ""
board.string_to_tiles(to_view)

while running:
    image = pygame.Surface((640, 480))
    pygame.draw.rect(image, (255, 255, 255), (0, 0, 640, 480))
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False
        
    screen.fill('white')
    board.render(image)
    screen.blit(image, (0, 0))

    if board.solved():
        txt = my_font.render("You did it!", 0, (0, 0, 0))
        screen.blit(txt, (128, 400))

    pygame.display.flip()
    clock.tick(60)
    
pygame.quit()